// Removed members are archived and marked suspended. Only a current,
// active member occupies a seat — the same predicate as countActiveMembers.
const seats = db
  .select({ value: count() })
  .from(members)
  .where(
    and(
      eq(members.orgId, orgId),
      eq(members.status, "active"),
      isNull(members.archivedAt),
    ),
  )
  .get();

